SELECT CASE WHEN quantity >= 249 THEN 'high' WHEN quantity >= 102 THEN 'mid' ELSE 'low' END AS quantity_bucket, store_id, CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, ROUND(AVG(quantity), 2) AS avg_quantity, MAX(last_restock) AS last_last_restock FROM inventory WHERE last_restock >= '2023-10-20' GROUP BY 1, 2, 3 HAVING ROUND(AVG(quantity), 2) < 67;
